INSERT INTO converted_files (title, description, file_url, file_name, s3_key, size_bytes) VALUES ('Счет Трейд Ресурс УТ-68 отгрузка-1 21.10 в загрузку OData', 'Счёт ООО «Эй Джи Групп» № УТ-68 от 13.10.2026 по «Отгрузке-1» от 21.10.2026 (РБ), правило «Создание файла для OData». Восемь колонок: Артикул (из отгрузки, текстом), Штрихкод (пусто), Наименование (как в отгрузке = как в счёте), Количество (из отгрузки), Цена с НДС 22% (из счёта), Страна, Номер ГТД, Номер РНПТ (пусто — нет в исходниках). 47 строк в порядке отгрузки. Расхождение: в строке 7 отгрузки (Овощечистка (500), 485 шт) стоял артикул KBF25-250110-242 — по согласованию заменён на KBF25-250110-500 из счёта. Количество по всем позициям не превышает счёт (частичная отгрузка). Итог: 6 294 шт, 1 472 816,32 руб.', '/converted/schet-treid-resurs-ut-68-otgruzka-1-21-10-v-zagruzku-odata.xlsx', 'Счет Трейд Ресурс УТ-68 отгрузка-1 21.10 в загрузку OData.xlsx', 'converted/schet-treid-resurs-ut-68-otgruzka-1-21-10-v-zagruzku-odata.xlsx', 8479);